"""Final commercial draft audit only; AR/AP, payments and bank matching deferred."""
from create_pysb_historical_invoice_drafts import Run
from inspect_pysb_historical_invoices import OUT
from execute_pysb_stock_migration import save,rid,index,require
from collections import Counter,defaultdict
import json,html
from historical_invoice_checks import require_manifest,validation_errors,extra_read_fields
def main():
 m=Run();manifest=json.loads((OUT/'invoice-draft-manifest.json').read_text(encoding='utf8'));before=json.loads((OUT/'invoice-preflight-snapshot.json').read_text(encoding='utf8'));docs=manifest['documents'];require(len(m.j['documents'])==len(docs) and all(r['status']=='verified' for r in m.j['documents'].values()),'Incomplete draft creation')
 require_manifest(docs)
 targetids=[r['target_id'] for r in m.j['documents'].values()];moves=index(m.b.read('account.move',targetids,['state','move_type','company_id','partner_id','currency_id','amount_untaxed','amount_tax','amount_total','invoice_date','invoice_date_due','date','x_studio_v14_refererce','invoice_line_ids']+extra_read_fields(docs)));require(len(set(targetids))==len(docs),'Duplicate target ids');require(all(x['state']=='draft' and rid(x['company_id'])==1 for x in moves.values()),'Unexpected draft state/company');rows=[];totals=defaultdict(lambda:{'source':0.,'target':0.,'count':0});currencies=index(before['masters']['res.currency']['source']);errors=[]
 lines=index(m.b.read('account.move.line',[lid for move in moves.values() for lid in move['invoice_line_ids']],['balance','amount_currency']))
 for document in docs:errors.extend({'source':document['source_name'],**e} for e in validation_errors(document,moves[m.j['documents'][str(document['source_id'])]['target_id']],lines))
 for d in docs:
  rec=m.j['documents'][str(d['source_id'])];t=moves[rec['target_id']];s=d['source'];delta=t['amount_total']-s['amount_total'];currency=currencies[rid(s['currency_id'])]['name'];key=s['move_type']+'/'+('CNY' if currency=='CNH' else currency);totals[key]['source']+=s['amount_total'];totals[key]['target']+=t['amount_total'];totals[key]['count']+=1
  if abs(delta)>0.00501 or t['x_studio_v14_refererce']!=s['name']:errors.append({'source':s['name'],'target':t['id'],'delta':delta})
  rows.append({'source_id':s['id'],'source_reference':s['name'],'target_id':t['id'],'kind':'Invoice' if s['move_type']=='out_invoice' else 'Bill','currency':currency,'target_currency':'CNY' if currency=='CNH' else currency,'invoice_date':t['invoice_date'],'accounting_date':t['date'],'due_date':t['invoice_date_due'],'source_total':s['amount_total'],'target_total':t['amount_total'],'delta':delta,'state':t['state'],'line_count':len(t['invoice_line_ids']),'unlinked_outside_scope_lines':d['unlinked_outside_scope_lines'],'url':f"https://py-staging.odoo.com/web#id={t['id']}&model=account.move&view_type=form"})
 external=m.b.search_read('ir.model.data',[['module','=','pysb_v14'],['model','=','account.move'],['res_id','in',targetids]],['name','res_id']);require(len(external)==len(docs) and len({x['name'] for x in external})==len(docs),'Provenance count mismatch')
 # Commercial values of existing posted invoices/bills remain unchanged.
 old=m.b.read('account.move',[x['id'] for x in before['target_moves_before']],['state','amount_untaxed','amount_tax','amount_total','invoice_date','date','partner_id','currency_id']);old_index=index(before['target_moves_before']);unchanged=all(all(x[k]==old_index[x['id']][k] for k in x if k!='id') for x in old);require(unchanged,'Existing posted document changed')
 productbaseline={x['id']:x for x in __import__('execute_pysb_stock_migration').load('execution-journal.json')['baseline_products']};products=m.b.read('product.product',list(productbaseline),['name','default_code','barcode','tracking','uom_id','packing_ratio','active']);masters_preserved=all(all(x[k]==productbaseline[x['id']][k] for k in x if k!='id') for x in products);require(masters_preserved,'Product master changed')
 require(not errors,'Final amount/reference mismatch');summary={'scope_so':953,'scope_po':86,'documents':len(docs),'types':dict(Counter(x['kind'] for x in rows)),'states':dict(Counter(x['state'] for x in rows)),'errors':errors,'existing_posted_documents_preserved':unchanged,'product_masters_preserved':masters_preserved,'customer_or_account_master_creation':False,'mixed_order_documents':sum(bool(x['unlinked_outside_scope_lines']) for x in rows),'deferred_document_types':dict(Counter(x['move_type']+'/'+x['state'] for x in manifest['deferred_documents'])),'posting_payments_reconciliation_bank_matching':'not performed, deferred by Bruce','totals_by_type_currency':dict(totals)};save(OUT/'invoice-draft-final-report.json',{'summary':summary,'rows':rows,'deferred_documents':manifest['deferred_documents']})
 fields=['source_reference','kind','target_id','invoice_date','accounting_date','due_date','target_currency','source_total','target_total','delta','line_count','state'];labels=['Tham chiếu v14','Loại','ID v19','Ngày hóa đơn','Ngày kế toán','Hạn trả','Tiền tệ v19','Tổng v14','Tổng v19','Chênh lệch','Số dòng','Trạng thái'];body=''.join('<tr>'+''.join('<td>'+('<a href="'+html.escape(r['url'],quote=True)+'">'+html.escape(str(r[k]))+'</a>' if k=='target_id' else html.escape(str(r[k])))+'</td>' for k in fields)+'</tr>' for r in rows);page='<meta charset="utf-8"><title>PYSB — Invoice/Bill nháp</title><style>body{font:14px Arial;margin:24px}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:6px}th{background:#eef4fa}</style><h1>Pao Yeang — Invoice/Bill lịch sử đã tạo nháp</h1><p>Chọn từ 953 SO và 86 PO đã chốt, không lọc ngày hóa đơn. Đã tạo 960 Invoice và 97 Bill; ngày hóa đơn 01/07–30/09/2026. Tất cả ở nháp, chưa post, tạo payment, reconcile hoặc đối chiếu bank statement. Tham chiếu v14 được giữ tại trường v14 Reference (studio).</p><p>Giữ đầy đủ dòng hóa đơn. Có 5 hóa đơn chứa dòng từ đơn ngoài phạm vi: các dòng chưa có SO/PO đích được giữ nguyên nội dung và ghi trong JSON. 17 Credit Note và 6 hóa đơn đã hủy để bước sau. CNH → CNY theo ánh xạ đã chốt.</p><pre>'+html.escape(json.dumps(summary,ensure_ascii=False,indent=2))+'</pre><table><tr>'+''.join('<th>'+k+'</th>' for k in labels)+'</tr>'+body+'</table>';(OUT/'PYSB_Invoice_Bill_Draft_Review.html').write_text(page,encoding='utf8');print(json.dumps(summary,ensure_ascii=False),flush=True)
if __name__=='__main__':main()
